 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Contact support</h1>
       <p class="lede">Send us a message and our support team will get back to you as soon as possible.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input id="full-name" name="fullName" type="text" autocomplete="name" required>
           <p class="field-message" id="full-name-error" hidden>Error: Please enter your full name.</p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
           <input id="email-address" name="emailAddress" type="email" autocomplete="email" required>
           <p class="field-message" id="email-address-error" hidden>Error: Please enter a valid email address.</p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" aria-describedby="phone-number-hint">
           <p class="field-hint" id="phone-number-hint">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
           <p class="status" id="form-status" role="status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');
     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         message: 'Error: Please enter your full name.'
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         message: 'Error: Please enter a valid email address.'
       }
     ];

     function setError(field, isInvalid) {
       if (isInvalid) {
         field.input.setAttribute('aria-invalid', 'true');
       } else {
         field.input.removeAttribute('aria-invalid');
       }
       field.error.hidden = !isInvalid;
       if (isInvalid) {
         field.error.textContent = field.message;
         field.input.setAttribute('aria-describedby', field.error.id);
       } else {
         field.input.removeAttribute('aria-describedby');
       }
     }

     function validateField(field) {
       const isValid = field.input.validity.valid && field.input.value.trim().length > 0;
       setError(field, !isValid);
       return isValid;
     }

     fields.forEach((field) => {
       field.input.addEventListener('blur', () => validateField(field));
       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       status.textContent = '';

       const invalidField = fields.find((field) => !validateField(field));
       if (invalidField) {
         invalidField.input.focus();
         return;
       }

       status.textContent = 'Thanks — your message is ready to send.';
       form.reset();
       fields.forEach((field) => setError(field, false));
     });
   </script>
 </body>
 </html>

